from .aashell import execute_aashell_command
from re import search, finditer

LNCEL_KEY = b'lcr'


def get_cell_mapping(aashell_port='15007'):
    """
    Updates cell mapping and returns cell mapping from AaShell in dict format
    :return: cell mapping as dict
    """
    node_id = _get_node_id(aashell_port=aashell_port)
    raw_cell_mapping = execute_aashell_command(
        'getCellMapping @RROMexe #{0}'.format(node_id), aashell_port=aashell_port
    )
    cell_mapping_dict = _make_mapping_dict(raw_cell_mapping)

    return cell_mapping_dict


def _get_mapping_data_lines(raw_mapping_data):
    lines = raw_mapping_data.strip().splitlines()
    return [line.split() for line in lines]


def _create_mapping_dicts_list(mapping_keys, cell_values):
    return [dict(list(zip(mapping_keys, cell_values_per_cell))) for cell_values_per_cell in cell_values]


def _make_mapping_dict(raw_mapping_data):
    """ Takes raw mapping output from aashell
    'lcr lnCel pci eutraCelId chBw noRx CaPoolId ULCoMP L1PoolType              L2PoolType                UEC'\
    '     CELLC   MACCELL MACULTTI   MACDLTTI   TUPU    DL-PHY  UL-PHY\n11  1     11  267        20M  0    1'\
    '        -      FSMr3_FDD_L1_Basic      FSMr3_FDD_L2_12Core_Basic 0x120d  0x120d  0x1273'\
    '  0x00000000 0x00000000 0x1272  0x1244  0x1241\n12  2     12  268        20M  0    2        -'\
    '      FSMr3_FDD_L1_Basic      FSMr3_FDD_L2_12Core_Basic 0x120d  0x120d  0x1273  0x00000000 0x00000000'\
    ' 0x1272  0x1264  0x1261\n13  3     13  269        20M  0    3        -      FSMr3_FDD_L1_Basic'\
    '      FSMr3_FDD_L2_12Core_Basic 0x120d  0x120d  0x1273  0x00000000 0x00000000 0x1272  0x1284  0x1281\n'

    and returns mapping dict

    {'11': {'TUPU': '0x1272', 'UL-PHY': '0x1241', 'MACCELL': '0x1273', 'lcr': '11',
                                     'L1PoolType': 'FSMr3_FDD_L1_Basic', 'MACDLTTI': '0x00000000', 'noRx': '0',
                                     'L2PoolType': 'FSMr3_FDD_L2_12Core_Basic', 'UEC': '0x120d', 'chBw': '20M',
                                     'CaPoolId': '1', 'eutraCelId': '267', 'pci': '11', 'DL-PHY': '0x1244',
                                     'CELLC': '0x120d', 'MACULTTI': '0x00000000', 'ULCoMP': '-', 'lnCel': '1'},
                              '13': {'TUPU': '0x1272', 'UL-PHY': '0x1281', 'MACCELL': '0x1273', 'lcr': '13',
                                     'L1PoolType': 'FSMr3_FDD_L1_Basic', 'MACDLTTI': '0x00000000', 'noRx': '0',
                                     'L2PoolType': 'FSMr3_FDD_L2_12Core_Basic', 'UEC': '0x120d', 'chBw': '20M',
                                     'CaPoolId': '3', 'eutraCelId': '269', 'pci': '13', 'DL-PHY': '0x1284',
                                     'CELLC': '0x120d', 'MACULTTI': '0x00000000', 'ULCoMP': '-', 'lnCel': '3'},
                              '12': {'TUPU': '0x1272', 'UL-PHY': '0x1261', 'MACCELL': '0x1273', 'lcr': '12',
                                     'L1PoolType': 'FSMr3_FDD_L1_Basic', 'MACDLTTI': '0x00000000', 'noRx': '0',
                                     'L2PoolType': 'FSMr3_FDD_L2_12Core_Basic', 'UEC': '0x120d', 'chBw': '20M',
                                     'CaPoolId': '2', 'eutraCelId': '268', 'pci': '12', 'DL-PHY': '0x1264',
                                     'CELLC': '0x120d', 'MACULTTI': '0x00000000', 'ULCoMP': '-', 'lnCel': '2'}}
    """
    mapping_data_lines = _get_mapping_data_lines(raw_mapping_data)
    mapping_keys = mapping_data_lines[0]
    cell_values = mapping_data_lines[1:]
    mapping_dicts_list = _create_mapping_dicts_list(mapping_keys, cell_values)
    return {mapping_dict[LNCEL_KEY]: mapping_dict for mapping_dict in mapping_dicts_list}


def _get_node_id(aashell_port='15007'):
    """
    Return address of the node where RROMexe is running
    :return address of the node where RROMexe is running
    :raise ERROR: Cannot find process RROMexe in known nodes
    :raise ERROR: Cannot fetch address of the node where RROMexe is running
    """
    nodes = []
    node_id = None

    output = execute_aashell_command('nodes -p RROMexe', aashell_port=aashell_port)
    if not output:
        raise Exception('ERROR: Cannot fetch address of the node where RROMexe is running')
    nodes_index = [i.start() for i in finditer('node', output.decode())]

    for (i, val) in enumerate(nodes_index[:-1]):
        node = output[nodes_index[i] : nodes_index[i + 1]]
        nodes.append(node)
    nodes.append(output[nodes_index[-1] :])

    for node in nodes:
        if search('RROMexe', node.decode()) is not None:
            node_id = search(r'0x.*,', node.decode()).group().split(',')[0]
            return node_id

    if node_id is None:
        raise Exception("ERROR: Cannot find process RROMexe in known nodes")
